// Import-Skript fuer 26 verbleibende historische Dokumente
// Aufruf Trockenlauf: mongosh graupner_test --quiet --eval 'var DRY_RUN=true;' /home/graupner/import_verbleibende_26.js
// Aufruf ECHT:        mongosh graupner_test --quiet --eval 'var DRY_RUN=false;' /home/graupner/import_verbleibende_26.js

if (typeof DRY_RUN === 'undefined') { var DRY_RUN = true; }

print("=== MODUS: " + (DRY_RUN ? "TROCKENLAUF (nichts wird gespeichert)" : "ECHTER IMPORT") + " ===");
print("");

var ergebnisse = { erfolg: 0, uebersprungen: 0, kunde_fehlt: 0 };

function importiereDokument(kind, nummerFeld, nummerWert, nachnameRegex, alteDatenJSON, originalId) {
  var kunde = db.module_kunden.findOne({nachname: {$regex: nachnameRegex, $options: "i"}});
  if (!kunde) {
    print("KUNDE NICHT GEFUNDEN (" + nachnameRegex + ") -- " + nummerWert + " -- UEBERSPRUNGEN");
    ergebnisse.kunde_fehlt++;
    return;
  }

  var alteDaten = JSON.parse(alteDatenJSON);

  var pruefung = db[kind].findOne({id: originalId});
  if (pruefung) {
    print("BEREITS VORHANDEN (id " + originalId + ") -- " + nummerWert + " -- UEBERSPRUNGEN");
    ergebnisse.uebersprungen++;
    return;
  }

  var neuesDokument = Object.assign({}, alteDaten, {
    customer_id: kunde.id,
    customer_name: (kunde.vorname + " " + kunde.nachname).trim(),
    is_template: false,
    imported_historical: true,
    import_source: "emergent_export_2026-07-04",
    original_customer_name: alteDaten.customer_name
  });

  if (DRY_RUN) {
    print("WUERDE IMPORTIEREN: " + nummerWert + " -> Kunde: " + neuesDokument.customer_name + " (gefunden ueber '" + nachnameRegex + "')");
  } else {
    db[kind].insertOne(neuesDokument);
    print("ERFOLG: " + nummerWert + " importiert fuer Kunde " + neuesDokument.customer_name);
  }
  ergebnisse.erfolg++;
}


importiereDokument("quotes", "quote_number", "A-2026-0002", "Sch\u00f6rshusen", '{"id": "d0214573-aea4-4419-a173-b3852cfbbeb9", "quote_number": "A-2026-0002", "customer_id": "26b30586-93a3-460a-9082-00ebacd1baaf", "customer_name": "Marc Schörshusen", "customer_address": "Lottbeker Feld 51 , 22359 Hamburg", "positions": [{"type": "titel", "pos_nr": 0, "description": "Einrüstungskosten", "quantity": 0, "unit": "Stück", "price_net": 0, "labor_cost": 0}, {"type": "position", "pos_nr": 0, "description": "Elementdichtung entfernen – Elementflügeldichtungen fachgerecht entfernen – alte Dichtung entfernen – Nuten evtl. von Kleberesten befreien, Nuten reinigen und für die Montage neuer Dichtungen vorbereiten. Abrechnung nach Verbrauch", "quantity": 1, "unit": "lfm", "price_net": 12.45, "labor_cost": 0}, {"type": "position", "pos_nr": 0, "description": "Einrüstkosten/Sicherheitsrelevant – Einrüstkosten/sicherheitsrelevante Maßnahmen für die Aufstellung von Abdeckmaterial, sicherheitsrelevante Maßnahmen. Abrechnung nach Anzahl der Fenster, Türen, Objekte.", "quantity": 1, "unit": "Stk", "price_net": 42, "labor_cost": 0}, {"type": "position", "pos_nr": 0, "description": "Belastete Kunststoffdichtungen entsorgen – belastete Kunststoffdichtungen, die fachgerecht und ordnungsgemäß entsorgt werden müssen", "quantity": 1, "unit": "Stk", "price_net": 15, "labor_cost": 0}, {"type": "position", "pos_nr": 0, "description": "Elementdichtungen liefern - Elementhochleistungsdichtung passend liefern. Unsere Fenster- und Türendichtungen haben hervorragende Eigenschaften wie folgt: - Thermoplastisches Elastomer (TPE-S), Härte nach Shore A 30 bis A 80 +/-5. - Hervorragende UV-, Ozon- und Witterungsbeständigkeit - keine Rußauswaschungen - silikon- und halogenfrei. - Gute Beständigkeit gegen unverdünnte Laugen und Säuren sowie Salzlösungen aller Art. - Einsatzbereich von -40 Grad bis +110 Grad. Abrechnung nach Verbrauch.", "quantity": 1, "unit": "lfm", "price_net": 19.74, "labor_cost": 0}, {"type": "titel", "pos_nr": 0, "description": "Sonstige Kosten", "quantity": 0, "unit": "Stück", "price_net": 0, "labor_cost": 0}], "notes": "", "vortext": "Als eingetragener Tischlereibetrieb in der Handwerkskammer Hamburg freuen wir uns, dass Sie auf die Qualitätsprodukte der Tischlerei Graupner setzen. Gemäß unseren Erfahrungen „seit 1960“ tauschen wir ab einem Alter von 8–10 Jahren keine einzelnen Teile mehr aus. Die Gründe sind vielschichtig. Zum einen sind die verbauten Einzelteile alle gleich alt, und somit ist das Risiko eines nachfolgenden Defekts sehr hoch. Somit beginnen die Kosten erneut, ganz zu schweigen von der Möglichkeit, dass beim nächsten Mal der Schaden und damit der Reparaturaufwand höher sein kann. Des Weiteren sind nicht alle Teile unbegrenzt lieferbar. Viele der verbauten Altbeschläge erfüllen nicht den heutigen Sicherheitsstandard. Ein letzter Grund ist, dass viele der Fenster/Türen keine jährliche Wartung bekommen haben, was zur Folge hat, dass die Getriebeteile trocken laufen und sich möglicherweise aufgerieben haben. Eine echte Prüfung des verbauten Beschlags kann also nur erfolgen, wenn dieser fachgerecht demontiert wird! Und wenn er schon mal demontiert ist, sollte auch das neue Falzgetriebe montiert werden. Im Übrigen: Wenn Sie ein neues Falzgetriebe von uns montieren lassen, haben Sie eine Garantie von 5 Jahren auf unsere Arbeit. Der Lieferant gewährt bei dieser Konstellation auch 5 Jahre auf das verbaute Falzgetriebe. Sie erhalten heute das gewünschte Preisangebot freibleibend, das wir sehr günstig für Sie kalkuliert haben. Die Arbeiten werden sehr sauber ausgeführt; Sie benötigen hinterher keinen Maurer und keinen Maler.", "schlusstext": "Haben Sie noch Fragen zu diesem Angebot?\\nWir beantworten sie gern!\\n\\nSie erreichen uns täglich von 7 bis 17 Uhr unter der Telefonnummer 01515 7437 305 oder +49 40 555 6 77 44.\\nSelbstverständlich nehmen wir unter dieser Nummer auch Ihre Bestellung entgegen.\\nMit freundlichen Grüßen\\nRalph Graupner Senior", "betreff": "Angebot Nr. – Fensterreparatur", "discount": 0, "discount_type": "percent", "vat_rate": 19, "subtotal_net": 89.19, "vat_amount": 16.95, "total_gross": 106.14, "status": "Entwurf", "is_template": false, "valid_until": "2026-06-10T06:26:26.699941+00:00", "show_lohnanteil": false, "lohnanteil_custom": "", "created_at": "2026-05-11T06:26:26.700107+00:00", "followup_pushed_at": "2026-06-19T09:41:30.343305+00:00", "followup_sent": true}', "d0214573-aea4-4419-a173-b3852cfbbeb9");
