importiereDokument("quotes", "quote_number", "A-2026-0009", "Leisenheimer", '{"id": "eea76811-560d-403e-88fe-b3c0a64c0222", "quote_number": "A-2026-0009", "customer_id": "bfb0b32b-7833-486e-ad7d-59b216f39095", "customer_name": "Kristin Leisenheimer", "customer_address": "Hegestraße 78 ,  Hamburg", "positions": [{"type": "titel", "pos_nr": 0, "description": "Wohnzimmer / Terrasse / Balkon", "quantity": 0, "unit": "Stück", "price_net": 0, "labor_cost": 0}, {"type": "position", "pos_nr": 0, "description": "Einrüstkosten/Sicherheitsrelevant - Einrüstkosten/Sicherheitsrelevante Maßnahmen für Aufstellung von Abdeckmaterial, sicherheitsrelevanten Maßnahmen. Abrechnung nach Anzahl Fenster, Türen, Objekte.", "quantity": 1, "unit": "Stk", "price_net": 42, "labor_cost": 0}, {"type": "position", "pos_nr": 0, "description": "Fachgerechte Reparatur der PSK-Tür\\nKippschiebeelement wie folgt reparieren.\\nMaterial auftragsspezifisch zusammenstellen und auf Lkw vertragen. Umlaufendes Getriebe: notwendige Teile demontieren, prüfen, reinigen und ggf. reparieren, wenn möglich. Wenn notwendig, defekte Getriebeteile fachgerecht ersetzen.\\nAlte Schiebeschlitten fachgerecht\\ndemontieren und durch neue Laufwagen ersetzen.\\n\\nAlles wieder fachgerecht montieren,\\neinstellen und auf Gängigkeit prüfen.\\nFehler aufnehmen und für später\\ndokumentieren.", "quantity": 1, "unit": "Stück", "price_net": 1205.13, "labor_cost": 0}, {"type": "titel", "pos_nr": 0, "description": "Materialkosten", "quantity": 0, "unit": "Stück", "price_net": 0, "labor_cost": 0}, {"type": "position", "pos_nr": 0, "description": "PSK-Laufwagen-Set liefern\\nPSK-Laufwagen als Kpl.-Set inkl.\\nAbdeckung liefern.\\n(*) abzgl. Nachlass:-8,00% (€ -70,40) = € 809,", "quantity": 1, "unit": "Stück", "price_net": 380, "labor_cost": 0}, {"type": "titel", "pos_nr": 0, "description": "Materialkosten nicht ermittelbar bei Besichtigung", "quantity": 0, "unit": "Stück", "price_net": 0, "labor_cost": 0}, {"type": "position", "pos_nr": 0, "description": "Materialkostenabrechnung nach\\nVerbrauch, umlaufendes Getriebe und\\nSchiene. Materialkosten, die während der Reparatur ermittelt werden und\\nnotwendig sind, werden nach Verbrauch abgerechnet.", "quantity": 1, "unit": "Stück", "price_net": 0, "labor_cost": 0}, {"type": "titel", "pos_nr": 0, "description": "Sonstige-Kosten", "quantity": 0, "unit": "Stück", "price_net": 0, "labor_cost": 0}, {"type": "position", "pos_nr": 0, "description": "Belastetes Alteisen fachgerecht entsorgen", "quantity": 1, "unit": "Stück", "price_net": 34.3, "labor_cost": 0}, {"type": "titel", "pos_nr": 0, "description": "KFZ-Vorhaltekosten für Werkstattwagen", "quantity": 0, "unit": "Stück", "price_net": 0, "labor_cost": 0}, {"type": "position", "pos_nr": 0, "description": "- Für Reparatur / Wartungsarbeiten\\neingesetztes KFZ. Tagessatz", "quantity": 1, "unit": "Stück", "price_net": 37.51, "labor_cost": 0}, {"type": "titel", "pos_nr": 0, "description": "Nachlass", "quantity": 0, "unit": "Stück", "price_net": 0, "labor_cost": 0}, {"type": "position", "pos_nr": 0, "description": "Nachlass", "quantity": 1, "unit": "Stück", "price_net": -200, "labor_cost": 0}], "notes": "", "vortext": "Sehr geehrte Frau Kristin Leisenheimer,\\n\\nals eingetragener Tischlereibetrieb in der Handwerkskammer Hamburg freuen wir uns, dass Sie auf die Qualitätsprodukte der Tischlerei Graupner setzen. Sie erhalten heute das gewünschte Preisangebot, freibleibend, das wir sehr günstig für Sie kalkuliert haben.", "schlusstext": "Die Beauftragung erfolgt somit nach unseren Allgemeinen Geschäftsbedingungen.\\n\\nArbeitsablauf: \\n1: Wir benötigen zeitnah Zugang zu dem Objekt zwecks detaillierter Materialbestimmung (3 Hersteller). \\n2: Terminierung und fachgerechte Ausführung inkl. Intensivprüfung für die Reparatur.\\n\\nBitte beachten Sie: Sollten Sie nicht am Tage der Fertigstellung die Arbeiten abnehmen können,\\nsorgen Sie bitte für eine Person Ihres Vertrauens, welche am Fertigstellungstermin die Arbeiten\\nabnehmen und gegenzeichnen kann.\\n\\nZahlungsbedingungen: Bei Auftragserteilung erfolgt eine Vorauszahlung (Materialanteil) in Höhe\\nvon 500 € Euro.\\n\\nMaterialkosten, die während der Reparatur ermittelt werden (sichtbar und prüffähig durch Demontage) und notwendig sind, werden nach Verbrauch abgerechnet.\\n\\nDie Arbeiten beginnen umgehend nach Eingang der Vorauszahlung (geben Sie uns bitte 3 mögliche Termine vor.). Die Restsumme wird sofort nach Fertigstellung (innerhalb von 5 Tagen) fällig. Die Beauftragung erfolgt somit nach unseren Allgemeinen Geschäftsbedingungen.\\n\\nBeachten Sie bitte, dass die Rechnung sofort nach Fertigstellung auf der Baustelle zu begleichen ist.\\n\\nBezahloptionen:\\n\\nOnlineüberweisung: Wenn die Arbeiten fertiggestellt sind, erhalten Sie unsere Rechnung sofort online. Sie überweisen innerhalb von 5 Tagen.\\n\\nZum Zeichen des beiderseitigen Einverständnisses bitten wir Sie, ein Exemplar der\\nAuftragsbestätigung unterschrieben an uns zurückzusenden oder unseren Mitarbeitern vor Beginn\\nder Arbeiten auszuhändigen.\\n\\nVielen Dank\\n\\n\\nHiermit erteile ich oben genannten Auftrag. \\n\\n\\n_______________________________ __________ \\n                                              Name                                                       Datum:", "betreff": "PSK-Parallelschiebekipptür fachgerecht reparieren inkl. großer Wartung", "discount": 0, "discount_type": "percent", "vat_rate": 19, "subtotal_net": 1498.94, "vat_amount": 284.8, "total_gross": 1783.74, "status": "Versendet", "is_template": false, "valid_until": "2026-07-17T07:28:24.259129+00:00", "followup_sent": false, "show_lohnanteil": false, "lohnanteil_custom": null, "created_at": "2026-06-17T07:28:24.259455+00:00"}', "eea76811-560d-403e-88fe-b3c0a64c0222");
